@startuml

class ElevatorController {}

class Elevator {
  + direction : string
  + currentFloor : int
  + idle : boolean
  + move()
  + stop()
  + status()
}

class ElevatorButton {
  + floorNumber : int
  + isLit : boolean
}

class FloorButton {
  + floorNumber : int
  + direction : string
  + isLit : boolean
}

class Floor {}

ElevatorController "1" -- "*" Elevator : manages
Elevator "1" *-- "*" ElevatorButton : has
Floor "1" -- "*" FloorButton : has
ElevatorController ..> Elevator : controls

@enduml

